use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap,io::Read};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){let r=Path::new("/tmp/zopro-g2-tree-c7a");let mut pins=BTreeMap::new();let mut rows=Vec::new();for(name,old)in[("baseline","/tmp/zopro-g2-level-tree"),("candidate","/tmp/zopro-g2-prefix-tree")]{let old=Path::new(old);let mut sources=0;let mut external=0;for(p,h)in read(old.join("source-pins.json")).as_object().unwrap(){let target=if let Ok(rel)=Path::new(p).strip_prefix(old.join("candidate")){sources+=1;r.join(format!("{name}-source")).join(rel)}else{external+=1;Path::new(p).to_path_buf()};assert_eq!(hash(&target),h.as_str().unwrap(),"snapshot/input mismatch {}",target.display());pins.insert(target.display().to_string(),h.as_str().unwrap().to_owned());}let new=r.join(format!("{name}-probe.rs"));assert_eq!(hash(&new),hash(old.join("probe.rs")));pins.insert(new.display().to_string(),hash(new));rows.push(json!({"variant":name,"source_files":sources,"external_pins":external,"driver_byte_identical":true}));}
 for rel in ["audit.rs","audit","closeout.rs","closeout","cloud.rs","cloud","transfer.rs","transfer","sigv4.rs","audit-cleanup.rs","audit-cleanup","finalize-image.rs","finalize-image","prepare-image.rs","prepare-image","prepare-build.rs","prepare-build","runner.rs","runner","design.md","helper-sha256.txt"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}
 for(rel,h)in read("/tmp/zopro-grouping-module/production-source-manifest.json")["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel)),h.as_str().unwrap());}
 let a=json!({"status":"pass","source_snapshots":rows,"input_pins":pins,"production_sources_unchanged":true,"new_algorithms":false,"target":"znver4","adopted":false});fs::write(r.join("source-audit.json"),serde_json::to_vec_pretty(&a).unwrap()).unwrap();println!("Both source snapshots/drivers and all prior source/input pins agree;{}auditpins",pins.len());}
